//! Import command for migrating data from other AI systems.use std::path::PathBuf;use std::sync::Arc;use clap::Subcommand;#[cfg(feature = "import")]use crate::import::ImportOptions;#[cfg(feature = "import")]use crate::import::openclaw::OpenClawImporter;/// Import data from other AI systems.#[derive(Subcommand, Debug, Clone)]pub enum ImportCommand {    /// Import from OpenClaw (memory, history, settings, credentials)    #[cfg(feature = "import")]    Openclaw {        /// Path to OpenClaw directory (default: ~/.openclaw)        #[arg(long)]        path: Option<PathBuf>,        /// Dry-run mode: show what would be imported without writing        #[arg(long)]        dry_run: bool,        /// Re-embed memory if dimensions don't match target provider        #[arg(long)]        re_embed: bool,        /// User ID for imported data (default: 'default')        #[arg(long)]        user_id: Option<String>,    },}/// Run an import command.#[cfg(feature = "import")]